import assert from "node:assert/strict";
import test from "node:test";
import { trimLabel } from "../src/trim-label.js";

test("empty input remains an empty string", () => {
  assert.equal(trimLabel(""), "");
});

test("whitespace-only input becomes an empty string", () => {
  assert.equal(trimLabel("  \t "), "");
});

test("surrounding whitespace is trimmed", () => {
  assert.equal(trimLabel("  hello  "), "hello");
});

